WITH p AS (SELECT %s::date d1,%s::date d2,coalesce(%s::text,'') ma_kho,coalesce(%s::text,'') ma_vt,%s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR (coalesce(u.ds_branchs,'')='' AND coalesce(u.ds_stocks,'')='') unrestricted FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT a.stt_rec,a.ln,a.ngay_ct,a.so_ct,a.ma_kho,a.ma_vt,a.ma_lo,a.so_seri_vt,a.ma_vi_tri,a.dvt,a.sl_nhap,a.sl_xuat,a.gia,a.tien_nhap,a.tien_xuat,a.status,count(*) OVER() total FROM public.ct70bsp a CROSS JOIN s WHERE s.ok IS NOT NULL AND a.ngay_ct BETWEEN s.d1 AND s.d2 AND(s.ma_kho='' OR a.ma_kho=ANY(string_to_array(s.ma_kho,',')))AND(s.ma_vt='' OR a.ma_vt=ANY(string_to_array(s.ma_vt,','))) AND (s.unrestricted OR EXISTS(SELECT 1 FROM public.dmkho w WHERE w.ma_kho=a.ma_kho AND w.ma_dvcs=ANY(string_to_array(s.bs,',')))) ORDER BY a.ngay_ct DESC,a.so_ct,a.ln LIMIT(SELECT lim FROM p);
